/**
 * Post-processes the OpenAPI specification generated by `protoc-gen-connect-openapi`
 * into an OpenAPI 3.2.0 document covering the full single-port `PuppetServer` HTTP
 * surface (`BearerAuth`, `GET /events` SSE `itemSchema`, `POST /files`, `GET /files/{id}`,
 * and `GET /healthz`), and emits a WinterTC-compatible pure-ESM TypeScript module at
 * `src/generated/openapi.ts`.
 */
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

interface OpenApiDocument {
  openapi?: string
  info?: Record<string, unknown>
  paths?: Record<string, unknown>
  components?: {
    securitySchemes?: Record<string, unknown>
    schemas?: Record<string, unknown>
    [key: string]: unknown
  }
  security?: Array<Record<string, unknown>>
  [key: string]: unknown
}

/**
 * Enrich a Connect-generated OpenAPI 3.1 document with OpenAPI 3.2.0 metadata,
 * `BearerAuth` security scheme, and plain-HTTP `fallback` routes (`/events`,
 * `/files`, `/files/{id}`, `/healthz`).
 */
export function enrichOpenApiDocument (
  doc: OpenApiDocument,
  version: string,
): OpenApiDocument {
  const enriched: OpenApiDocument = {
    ...doc,
    openapi: '3.2.0',
    info: {
      title: 'Wechaty Puppet Service API',
      version,
      description: 'Multi-protocol ConnectRPC & OpenAPI 3.2 interface for Wechaty Puppet Service.',
    },
    components: {
      ...doc.components,
      securitySchemes: {
        ...doc.components?.securitySchemes,
        BearerAuth: {
          type: 'http',
          scheme: 'bearer',
          description: 'Pass WECHATY_PUPPET_SERVICE_TOKEN as Bearer token.',
        },
      },
    },
    security: [{ BearerAuth: [] }],
    paths: {
      ...doc.paths,
      '/events': {
        get: {
          operationId: 'Puppet_EventsSSE',
          summary: 'Subscribe to real-time Puppet events via Server-Sent Events (SSE)',
          tags: ['wechaty.Puppet'],
          responses: {
            '200': {
              description: 'Continuous SSE stream of Wechaty Puppet events',
              content: {
                'text/event-stream': {
                  itemSchema: {
                    type: 'object',
                    required: ['event', 'data'],
                    properties: {
                      id: { type: 'string' },
                      event: {
                        type: 'string',
                        description: 'Wechaty PuppetEventName (e.g., message, scan, login, heartbeat)',
                      },
                      retry: { type: 'integer', minimum: 0 },
                      data: {
                        type: 'string',
                        contentMediaType: 'application/json',
                        contentSchema: { type: 'object', additionalProperties: true },
                      },
                    },
                  },
                },
              },
            },
          },
        },
      },
      '/files': {
        post: {
          operationId: 'Puppet_FilesUpload',
          summary: 'Upload binary media to stage a FileBox handle for MessageSendFile',
          tags: ['wechaty.Puppet'],
          parameters: [
            {
              name: 'X-File-Name',
              in: 'header',
              required: false,
              schema: { type: 'string' },
              description: 'Optional filename for the uploaded media.',
            },
          ],
          requestBody: {
            required: true,
            content: {
              'application/octet-stream': {
                schema: { type: 'string', format: 'binary' },
              },
            },
          },
          responses: {
            '201': {
              description: 'Staged file metadata',
              content: {
                'application/json': {
                  schema: {
                    type: 'object',
                    required: ['id', 'url', 'name', 'mimeType', 'size'],
                    properties: {
                      id: { type: 'string' },
                      url: { type: 'string' },
                      name: { type: 'string' },
                      mimeType: { type: 'string' },
                      size: { type: 'integer', minimum: 0 },
                    },
                  },
                },
              },
            },
          },
        },
      },
      '/files/{id}': {
        get: {
          operationId: 'Puppet_FilesDownload',
          summary: 'Download staged upload or Puppet media/avatar FileBox by ID',
          tags: ['wechaty.Puppet'],
          parameters: [
            {
              name: 'id',
              in: 'path',
              required: true,
              schema: { type: 'string' },
            },
            {
              name: 'kind',
              in: 'query',
              required: false,
              schema: {
                type: 'string',
                enum: ['staged', 'message', 'contact-avatar', 'room-avatar'],
              },
            },
          ],
          responses: {
            '200': {
              description: 'Binary file stream',
              content: {
                'application/octet-stream': {
                  schema: { type: 'string', format: 'binary' },
                },
              },
            },
          },
        },
      },
      '/healthz': {
        get: {
          operationId: 'Puppet_Healthz',
          summary: 'Lightweight HTTP health probe',
          tags: ['grpc.health.v1.Health'],
          security: [],
          responses: {
            '200': {
              description: 'Service is healthy',
              content: {
                'application/json': {
                  schema: {
                    type: 'object',
                    required: ['status'],
                    properties: {
                      status: { type: 'string' },
                    },
                  },
                },
              },
            },
          },
        },
      },
    },
  }

  return enriched
}

async function main (): Promise<void> {
  const pkgRoot = path.resolve(import.meta.dirname, '..')
  const pkgJsonPath = path.join(pkgRoot, 'package.json')
  const openApiInputPath = path.join(pkgRoot, 'openapi', 'wechaty', 'puppet.openapi.json')
  const openApiTsPath = path.join(pkgRoot, 'src', 'generated', 'openapi.ts')

  const pkg = JSON.parse(await readFile(pkgJsonPath, 'utf8')) as { version: string }
  const rawDoc = JSON.parse(await readFile(openApiInputPath, 'utf8')) as OpenApiDocument
  const enriched = enrichOpenApiDocument(rawDoc, pkg.version)

  const jsonOutput = `${JSON.stringify(enriched, null, 2)}\n`
  await writeFile(openApiInputPath, jsonOutput, 'utf8')

  const tsOutput = [
    '/** @generated by scripts/enrich-openapi.ts — do not edit manually. */',
    `export const openApiSpec = ${JSON.stringify(enriched, null, 2)} as const`,
    '',
  ].join('\n')
  await writeFile(openApiTsPath, tsOutput, 'utf8')
}

if (import.meta.main) {
  await main()
}
